insert into i18n_bundles (locale, code, value) values ('ps', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'ما له عمر (رض) سره د اختر لمانځه وکړ؛ هغه لومړی لمونځ ادا کړ او بیا یې خطبه وکړه. بیا یې وویل: رسول الله صلی الله علیه وسلم د دې دوو ورځو روژه منع کړې ده. د قربان اختر ورځ تاسو د خپلو قربانیو غوښه خورئ، او د فطر اختر ورځ تاسو خپله روژه ماتوئ.');
